  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Reconhecer diferenças e acolher sem expor ninguém', 'Pessoas podem compartilhar algumas características e diferir em outras. Uma diferença não define o valor de alguém. Acolhimento aparece em regras e ações que permitem participação sem pressão ou exposição pessoal.', '## Compare uma característica por vez
Uma história pode mostrar dois personagens com algo em comum e outras preferências diferentes. Diga somente o que ela informa: “os dois gostam de histórias; um prefere desenhar e outro montar blocos”. Uma semelhança não torna as pessoas iguais em tudo, e uma diferença não torna ninguém melhor ou pior.

## Não transforme um exemplo em regra
Um personagem ou uma família de uma narrativa não representa automaticamente todas as pessoas. Descreva o que a fonte mostra e pergunte o que ainda não sabemos. Não adivinhe sentimentos, crenças ou costumes de alguém a partir de uma única característica.

## Acolher é permitir participação com escolha
Uma regra acolhedora distribui turnos, oferece opções e permite passar a vez sem punição. Pessoas podem participar falando, apontando, escutando ou contribuindo de outra forma adequada à atividade. Não force ninguém a compartilhar informações sobre religião, família, origem ou experiências pessoais.

## Se uma fala machucar
Interrompa a diminuição com uma frase simples, proteja a pessoa e procure apoio de um adulto. Não peça à criança atingida que explique sua identidade para merecer respeito nem que ensine toda a turma.

## Exemplo resolvido
Em um conto, Ana gosta de desenhar e Caio de montar blocos; ambos gostam de ouvir histórias. Podemos dizer que compartilharam o gosto por histórias e têm brincadeiras preferidas diferentes. Ao escolher a próxima atividade, a turma combina turnos. Não conclui que uma preferência é superior nem pede que uma criança conte algo privado.',
    'Uma história apresenta dois personagens: ambos gostam de ouvir histórias, mas escolhem brincadeiras diferentes. A turma registra uma semelhança e uma diferença. Para a atividade seguinte, combina turnos e permite observar antes de entrar. A regra acolhe sem exigir que alguém revele informação pessoal.', array['Use personagens fictícios e descreva apenas o que a história informa.', 'Nomeie uma semelhança e uma diferença sem ranquear.', 'Pergunte se uma regra permite escolha e participação sem exposição.', 'Não peça que uma criança represente uma família ou tradição.', 'Quando houver ofensa, procure apoio adulto sem exigir justificativa da pessoa atingida.']::text[], 20, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-religious-self-other-inclusion","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Escutar uma história curta com apoio.","Descrever preferências de personagens fictícios.","Reconhecer regras simples de turnos e brincadeiras."],"key_concepts":["Uma pessoa não se resume a uma característica.","Compartilhar uma preferência não significa ser igual em tudo.","Diferença não é defeito nem motivo de exclusão.","Acolhimento protege dignidade, privacidade e participação com escolha.","Um relato não representa automaticamente todas as pessoas de um grupo."],"progression":[{"stage":"FOUNDATION","focus":"Identificar uma semelhança e uma diferença em personagens fictícios.","questionIds":["v5-re-inclusion-probe-01","v5-re-inclusion-probe-02","v5-re-inclusion-probe-03","v5-re-inclusion-practice-01","v5-re-inclusion-practice-02","v5-re-inclusion-practice-03"]},{"stage":"APPLICATION","focus":"Escolher regras e ações que distribuam turnos e preservem escolhas.","questionIds":["v5-re-inclusion-practice-04","v5-re-inclusion-practice-05","v5-re-inclusion-practice-06","v5-re-inclusion-practice-07","v5-re-inclusion-practice-08"]},{"stage":"INTERMEDIATE","focus":"Evitar rótulos, generalizações e exposição em situações de convivência.","questionIds":["v5-re-inclusion-practice-09","v5-re-inclusion-practice-10","v5-re-inclusion-practice-11","v5-re-inclusion-transfer-01","v5-re-inclusion-transfer-02"]},{"stage":"ADVANCED_TRANSFER","focus":"Aplicar acolhimento a narrativas, perguntas pessoais e participação diversa.","questionIds":["v5-re-inclusion-transfer-03","v5-re-inclusion-transfer-04","v5-re-inclusion-transfer-05","v5-re-inclusion-transfer-06","v5-re-inclusion-transfer-07","v5-re-inclusion-lock-01","v5-re-inclusion-lock-02","v5-re-inclusion-lock-03","v5-re-inclusion-lock-04","v5-re-inclusion-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar comparação cuidadosa, privacidade e inclusão em novos contextos.","questionIds":["v5-re-inclusion-review-01","v5-re-inclusion-review-02","v5-re-inclusion-review-03","v5-re-inclusion-review-04","v5-re-inclusion-review-05","v5-re-inclusion-review-06","v5-re-inclusion-review-07","v5-re-inclusion-review-08","v5-re-inclusion-review-09"]}],"micro_explanations":[{"trigger":"ONE_FEATURE_LABEL","text":"Uma preferência conta uma parte da história, não tudo sobre uma pessoa. Use outras informações apresentadas e não crie uma regra sobre um grupo."},{"trigger":"DIFFERENCE_AS_RANK","text":"A história mostra diferença, não quem vale mais. Descreva a característica sem transformá-la em defeito ou prêmio."},{"trigger":"PRIVATE_DISCLOSURE","text":"Ninguém precisa revelar informação pessoal para participar. Ofereça a opção de passar a vez ou contribuir de outra forma."},{"trigger":"INCLUSION_WITHOUT_CHOICE","text":"Incluir não é obrigar. Combine turnos, opções e um convite sem punição para quem ainda não quer participar."}],"remediations":[{"misconception":"ONE_FEATURE_LABEL","prompt":"Volte à história e marque duas informações diferentes sobre o personagem. Reescreva a frase começando por “nesta história...” para não generalizar."},{"misconception":"DIFFERENCE_AS_RANK","prompt":"Troque “melhor/pior” por uma descrição observável. Depois proponha uma regra que permita a participação das duas preferências."},{"misconception":"PRIVATE_DISCLOSURE","prompt":"Reformule o convite para que a criança possa falar, apontar, escutar ou passar a vez sem explicar o motivo."},{"misconception":"INCLUSION_WITHOUT_CHOICE","prompt":"Revise a regra: há turnos, alternativas e opção sem punição? Ajuste até que a participação seja possível sem coerção."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Ensino Religioso do Ensino Fundamental","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["A fonte apresenta EF01ER01: identificar e acolher semelhanças e diferenças entre o eu, o outro e o nós."],"use":"Referência de escopo; este conteúdo usa cenários fictícios e não reivindica mapeamento oficial aprovado. Revisão pedagógica humana pendente."}],"copyright_note":"Personagens, situações, itens, feedback e atividade são autorais e fictícios. A referência oficial informa o escopo, sem copiar material e sem alegar aprovação humana ou mapeamento canônico.","authentic_activities":[{"id":"religious-inclusion-fictional-story-circle","title":"Uma roda de histórias com escolhas","objective":"Identificar semelhanças e diferenças em personagens fictícios e cocriar uma regra que permita participação respeitosa.","context":"A turma ouve uma história curta com personagens fictícios que têm gostos ou formas de participar diferentes; nenhuma criança é convidada a representar um grupo real.","materials":["História fictícia selecionada pelo educador","Cartões de personagens e preferências inventadas","Cartaz para registrar uma regra de convivência"],"instructions":"O educador lê a história. Em duplas, as crianças apontam uma informação em comum e uma diferente entre personagens. A turma propõe uma regra para a próxima brincadeira que distribua turnos, aceite formas diferentes de participar e permita passar a vez. Não solicitar relatos pessoais, nomes de tradições familiares nem explicações sobre crenças. Uma criança pode responder falando, apontando ou escutando.","evidence":"Descrição de uma semelhança e uma diferença apoiadas no conto, mais uma regra que ofereça participação sem hierarquizar personagens ou exigir revelação.","safety":"Usar apenas personagens e costumes ficcionais ou materiais aprovados pelo educador; interromper apelidos ou ridicularização; não pressionar crianças a compartilhar identidade, crença ou história familiar.","ageRange":"1º ano do Ensino Fundamental, com leitura mediada e exemplos curtos.","mediation":"O educador distingue observação de generalização, acolhe a opção de não falar e intervém em comentários que diminuam alguém. A rubrica avalia a resposta ao cenário fictício, nunca crenças ou identidades reais.","privacyGuard":"Não registrar ou coletar religião, origem, crenças, práticas familiares, imagem ou relato identificável de estudantes.","rubric":[{"criterion":"Comparação apoiada na história","emerging":"Ainda não identifica semelhança ou diferença com apoio.","developing":"Nomeia uma semelhança ou diferença com pergunta orientadora.","proficient":"Nomeia uma de cada e aponta evidência no conto."},{"criterion":"Descrição sem hierarquia","emerging":"Usa diferença como motivo para classificar ou excluir.","developing":"Evita ranking após mediação.","proficient":"Descreve a diferença sem atribuir valor ou regra universal."},{"criterion":"Regra de participação","emerging":"A proposta obriga, expõe ou exclui alguém.","developing":"Inclui uma opção, mas precisa de apoio para preservar escolha.","proficient":"Propõe turnos ou alternativas e permite passar a vez sem punição."}]}],"objective":"Descrever semelhanças e diferenças em personagens ou situações fictícias e escolher ações de convivência que preservem dignidade, privacidade e participação voluntária.","common_mistake":"Concluir que uma semelhança torna pessoas iguais em tudo, transformar uma preferência em rótulo, generalizar um costume de uma narrativa ou confundir participação com obrigação de falar e revelar informações pessoais.","estimated_minutes":20}'::jsonb
