  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-re-inclusion-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"FICTIONAL_CLASSMATES","statement":"No conto, Sara escolhe desenhar e Tomás prefere blocos. Os dois pedem para ouvir uma história. O que compartilham?","options":["O interesse em ouvir uma história.","A mesma brincadeira de montar blocos.","Todas as preferências e escolhas.","A ideia de que uma atividade é melhor que a outra."],"correctAnswer":"O interesse em ouvir uma história.","explanation":"O conto apresenta uma escolha em comum sem dizer que Sara e Tomás são iguais em tudo.","hint":"Use somente o interesse que aparece para os dois.","errorFocus":"Generalizar uma semelhança","misconceptions":{"A mesma brincadeira de montar blocos.":["SAME_PLAY"],"Todas as preferências e escolhas.":["IDENTICAL_IN_ALL"],"A ideia de que uma atividade é melhor que a outra.":["PREFERENCE_RANKING"]},"position":1},{"id":"v5-re-inclusion-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DESCRIBE","contextFamily":"FICTIONAL_DRAWING","statement":"Uma personagem prefere música e outra prefere silêncio. O que essa diferença permite concluir?","options":["A personagem que prefere música é sempre mais alegre.","Elas têm preferências diferentes; uma não é melhor por isso.","Quem prefere silêncio não pode brincar.","Uma preferência precisa ser mudada para participar."],"correctAnswer":"Elas têm preferências diferentes; uma não é melhor por isso.","explanation":"O texto informa gostos, não o valor das pessoas nem todos os seus sentimentos.","hint":"Separe a preferência da ideia de ser melhor ou pior.","errorFocus":"Transformar diferença em julgamento","misconceptions":{"A personagem que prefere música é sempre mais alegre.":["STEREOTYPE_FROM_PREFERENCE"],"Quem prefere silêncio não pode brincar.":["EXCLUSION"],"Uma preferência precisa ser mudada para participar.":["PREFERENCE_AS_DEFECT"]},"position":2},{"id":"v5-re-inclusion-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"RESPECT","contextFamily":"PRIVATE_STORY","statement":"Uma criança não quer contar algo da sua família durante uma roda. Qual atitude respeita sua escolha?","options":["Insistir até que ela conte.","Pedir a outra criança que conte por ela.","Aceitar que ela passe a vez e possa participar de outra forma.","Dizer que todos precisam revelar algo pessoal."],"correctAnswer":"Aceitar que ela passe a vez e possa participar de outra forma.","explanation":"Participar não exige compartilhar informações privadas.","hint":"Que opção mantém o convite sem pressionar?","errorFocus":"Forçar exposição pessoal","misconceptions":{"Insistir até que ela conte.":["PRESSURE"],"Pedir a outra criança que conte por ela.":["SPEAK_FOR_OTHER"],"Dizer que todos precisam revelar algo pessoal.":["MANDATORY_DISCLOSURE"]},"position":3},{"id":"v5-re-inclusion-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"INCLUDE","contextFamily":"PLAYGROUND_CHOICES","statement":"Algumas crianças querem desenhar e outras querem montar blocos. Como a turma pode organizar a escolha?","options":["Escolher sempre a atividade de uma só criança.","Afastar quem prefere outra opção.","Decidir que uma preferência vale mais que a outra.","Alternar as atividades ou oferecer mais de uma forma de participar."],"correctAnswer":"Alternar as atividades ou oferecer mais de uma forma de participar.","explanation":"Rodízio ou opções ampliam a participação sem classificar gostos.","hint":"Pense numa regra que dê vez a escolhas diferentes.","errorFocus":"Confundir maioria com preferência única válida","misconceptions":{"Escolher sempre a atividade de uma só criança.":["ONE_PERSON_DECIDES"],"Afastar quem prefere outra opção.":["EXCLUDE_DIFFERENCE"],"Decidir que uma preferência vale mais que a outra.":["RANK_PREFERENCES"]},"position":1},{"id":"v5-re-inclusion-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"STORY_CIRCLE","statement":"Na história, Ravi gosta de cantar e Joana gosta de escutar. Os dois gostam da mesma história. O que é correto dizer?","options":["Eles compartilham o gosto pela história e têm formas diferentes de participar da música.","Eles gostam de tudo do mesmo jeito.","Só quem canta participa da atividade.","Quem escuta não gosta da história."],"correctAnswer":"Eles compartilham o gosto pela história e têm formas diferentes de participar da música.","explanation":"Uma semelhança não apaga outras diferenças, e escutar também pode ser participação.","hint":"Nomeie uma coisa em comum e uma forma diferente de participar.","errorFocus":"Apagar diferenças por uma semelhança","misconceptions":{"Eles gostam de tudo do mesmo jeito.":["SAME_IN_ALL"],"Só quem canta participa da atividade.":["SINGING_ONLY"],"Quem escuta não gosta da história.":["LISTENING_AS_DISLIKE"]},"position":2},{"id":"v5-re-inclusion-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CHOOSE","contextFamily":"CLASSROOM_RULE","statement":"Qual combinado ajuda a turma a conversar quando as pessoas têm gostos diferentes?","options":["Interromper quem pensa diferente.","Esperar a vez, escutar e não usar apelidos para diminuir alguém.","Rir da escolha de outra pessoa.","Deixar falar só quem tem o mesmo gosto."],"correctAnswer":"Esperar a vez, escutar e não usar apelidos para diminuir alguém.","explanation":"Turnos e respeito permitem que todos participem sem humilhação.","hint":"O que protege quem está falando?","errorFocus":"Confundir discordância com permissão para ofender","misconceptions":{"Interromper quem pensa diferente.":["INTERRUPT"],"Rir da escolha de outra pessoa.":["RIDICULE"],"Deixar falar só quem tem o mesmo gosto.":["LIKE_ONLY"]},"position":3},{"id":"v5-re-inclusion-practice-04","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"RESPECT","contextFamily":"VOLUNTARY_SHARING","statement":"Uma professora convida a turma a falar de uma história que conhece. O que torna o convite respeitoso?","options":["Todos precisam contar uma lembrança de casa.","Quem passa a vez perde o direito de brincar.","Cada criança pode escolher se quer compartilhar ou passar a vez.","Um colega deve responder por quem ficou quieto."],"correctAnswer":"Cada criança pode escolher se quer compartilhar ou passar a vez.","explanation":"A escolha evita transformar a atividade em exposição obrigatória.","hint":"A criança pode escolher outra forma de participar?","errorFocus":"Confundir convite com obrigação","misconceptions":{"Todos precisam contar uma lembrança de casa.":["HOME_DISCLOSURE"],"Quem passa a vez perde o direito de brincar.":["PUNISH_PASS"],"Um colega deve responder por quem ficou quieto.":["PEER_DISCLOSURE"]},"position":4},{"id":"v5-re-inclusion-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"OBSERVE","contextFamily":"SHARED_GAME","statement":"Mila prefere jogar em dupla; Nuno prefere observar antes de entrar. O que ajuda a incluir os dois?","options":["Obrigar Nuno a começar imediatamente.","Dizer que observar nunca conta como participação.","Cancelar o jogo porque as preferências são diferentes.","Convidar Nuno sem pressão e combinar uma forma de entrar quando se sentir pronto."],"correctAnswer":"Convidar Nuno sem pressão e combinar uma forma de entrar quando se sentir pronto.","explanation":"Acolher pode incluir convite e escolha, respeitando ritmos de participação.","hint":"Como oferecer participação sem forçar?","errorFocus":"Tratar uma forma de participação como a única correta","misconceptions":{"Obrigar Nuno a começar imediatamente.":["FORCE_ENTRY"],"Dizer que observar nunca conta como participação.":["OBSERVING_AS_NOTHING"],"Cancelar o jogo porque as preferências são diferentes.":["CANCEL_DIFFERENCE"]},"position":5},{"id":"v5-re-inclusion-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"FICTIONAL_CUSTOM","statement":"Em um conto inventado, uma família acende uma lanterna numa noite especial. Outra família celebra de outra maneira. O que a turma pode dizer com respeito?","options":["As famílias têm costumes diferentes; o conto não diz que um é melhor.","O costume da primeira família é o único correto.","Todas as famílias fazem a mesma coisa.","Uma família deve explicar seu costume para a turma."],"correctAnswer":"As famílias têm costumes diferentes; o conto não diz que um é melhor.","explanation":"Uma história pode mostrar diferenças sem pedir que pessoas reais representem um grupo.","hint":"Descreva o que o conto mostra, sem criar uma regra para todos.","errorFocus":"Generalizar um costume ficcional","misconceptions":{"O costume da primeira família é o único correto.":["RANK_CUSTOMS"],"Todas as famílias fazem a mesma coisa.":["ALL_IDENTICAL"],"Uma família deve explicar seu costume para a turma.":["MANDATORY_REPRESENTATION"]},"position":6},{"id":"v5-re-inclusion-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INCLUDE","contextFamily":"CHOICE_ROTATION","statement":"A turma vai escolher três histórias para ouvir. Como distribuir a escolha de modo acolhedor?","options":["Deixar sempre a mesma pessoa escolher.","Cada criança pode sugerir uma história e a turma organiza turnos ou uma seleção combinada.","Escolher só histórias de quem fala mais alto.","Proibir sugestões diferentes da primeira."],"correctAnswer":"Cada criança pode sugerir uma história e a turma organiza turnos ou uma seleção combinada.","explanation":"Turnos e combinação permitem que gostos diferentes sejam considerados.","hint":"Como a turma pode ouvir mais de uma escolha?","errorFocus":"Usar autoridade ou volume como regra","misconceptions":{"Deixar sempre a mesma pessoa escolher.":["FIXED_CHOOSER"],"Escolher só histórias de quem fala mais alto.":["LOUDNESS_RULE"],"Proibir sugestões diferentes da primeira.":["FIRST_ONLY"]},"position":7},{"id":"v5-re-inclusion-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"HURTFUL_COMMENT","statement":"Uma criança diz que o jeito de outra participar é “esquisito”. O que um colega pode fazer?","options":["Repetir o comentário para todos ouvirem.","Obrigar a criança alvo a explicar sua família.","Dizer que não devemos diminuir alguém e chamar um adulto se precisar de ajuda.","Rir para não ficar de fora."],"correctAnswer":"Dizer que não devemos diminuir alguém e chamar um adulto se precisar de ajuda.","explanation":"A resposta protege a dignidade sem transferir à pessoa alvo a tarefa de se justificar.","hint":"Como interromper a ofensa sem expor mais a criança?","errorFocus":"Exigir que a pessoa alvo ensine os colegas","misconceptions":{"Repetir o comentário para todos ouvirem.":["AMPLIFY_COMMENT"],"Obrigar a criança alvo a explicar sua família.":["FORCE_EXPLANATION"],"Rir para não ficar de fora.":["JOIN_RIDICULE"]},"position":8},{"id":"v5-re-inclusion-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DESCRIBE","contextFamily":"MULTIPLE_INTERESTS","statement":"Em uma história, Iara gosta de plantas, jogos e histórias em áudio. Qual frase evita resumir Iara a uma característica?","options":["Iara só gosta de plantas.","Todas as crianças que gostam de plantas também gostam de jogos.","Iara precisa escolher um único interesse.","Iara tem vários interesses, como plantas, jogos e histórias em áudio."],"correctAnswer":"Iara tem vários interesses, como plantas, jogos e histórias em áudio.","explanation":"Uma descrição mais completa evita transformar um aspecto em rótulo.","hint":"Inclua mais de uma informação que o conto apresenta.","errorFocus":"Reduzir pessoa a uma característica","misconceptions":{"Iara só gosta de plantas.":["ONE_TRAIT_LABEL"],"Todas as crianças que gostam de plantas também gostam de jogos.":["GROUP_GENERALIZATION"],"Iara precisa escolher um único interesse.":["SINGLE_INTEREST_RULE"]},"position":9},{"id":"v5-re-inclusion-practice-10","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"FAIRNESS_WITH_DIFFERENCE","statement":"Uma atividade tem uma regra que impede uma criança de participar por causa de uma preferência ou costume. O que a turma deve fazer?","options":["Rever a regra com o educador para permitir participação sem obrigar ninguém a revelar algo pessoal.","Manter a regra porque ela vale igualmente para todos.","Pedir que a criança mude seu costume para entrar.","Mandar a criança explicar por que é diferente."],"correctAnswer":"Rever a regra com o educador para permitir participação sem obrigar ninguém a revelar algo pessoal.","explanation":"Uma regra pode parecer igual e ainda excluir; é preciso ajustar o acesso com respeito à privacidade.","hint":"A regra permite participação sem exposição ou coerção?","errorFocus":"Igualdade formal confundida com inclusão","misconceptions":{"Manter a regra porque ela vale igualmente para todos.":["SAME_RULE_ALWAYS_FAIR"],"Pedir que a criança mude seu costume para entrar.":["FORCE_CHANGE"],"Mandar a criança explicar por que é diferente.":["REQUIRE_DISCLOSURE"]},"position":10},{"id":"v5-re-inclusion-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"RESPOND","contextFamily":"STEREOTYPE_CORRECTION","statement":"Um personagem diz “toda pessoa que gosta de ficar quieta está triste”. Qual resposta é mais cuidadosa?","options":["A frase é sempre verdadeira.","Não sabemos o que cada pessoa sente só por observar uma preferência; podemos perguntar com respeito ou não presumir.","Quem está quieto deve sair da atividade.","É preciso escolher alguém para provar que a frase está errada."],"correctAnswer":"Não sabemos o que cada pessoa sente só por observar uma preferência; podemos perguntar com respeito ou não presumir.","explanation":"Uma característica observada não basta para afirmar o sentimento de todas as pessoas.","hint":"Diferencie o que foi visto do que foi suposto.","errorFocus":"Atribuir sentimento sem evidência","misconceptions":{"A frase é sempre verdadeira.":["UNIVERSAL_EMOTION"],"Quem está quieto deve sair da atividade.":["EXCLUDE_QUIET"],"É preciso escolher alguém para provar que a frase está errada.":["PERSON_AS_PROOF"]},"position":11},{"id":"v5-re-inclusion-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"COMMUNITY_STORY","statement":"Um livro mostra personagens com costumes diferentes que brincam juntos. Que conclusão respeita o que a história apresenta?","options":["Todas as pessoas têm o mesmo costume.","Um costume torna um personagem melhor que os outros.","Pessoas com costumes diferentes podem conviver e participar juntas.","A história prova que qualquer pessoa pensa igual."],"correctAnswer":"Pessoas com costumes diferentes podem conviver e participar juntas.","explanation":"A narrativa mostra convivência apesar das diferenças, sem apagar particularidades.","hint":"Use a ação que aparece na história, sem criar regras gerais.","errorFocus":"Generalizar ou hierarquizar diferenças","misconceptions":{"Todas as pessoas têm o mesmo costume.":["IDENTICAL_CUSTOM"],"Um costume torna um personagem melhor que os outros.":["RANKING"],"A história prova que qualquer pessoa pensa igual.":["UNIVERSAL_THOUGHT"]},"position":1},{"id":"v5-re-inclusion-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"CHOOSE","contextFamily":"NEW_STUDENT","statement":"Uma criança nova prefere observar a brincadeira antes de participar. Qual convite preserva sua escolha?","options":["“Você tem que brincar agora.”","“Só pode ficar aqui se contar algo da sua família.”","“Vamos decidir por você.”","“Você pode olhar primeiro; se quiser, depois escolhe como entrar.”"],"correctAnswer":"“Você pode olhar primeiro; se quiser, depois escolhe como entrar.”","explanation":"O convite oferece possibilidade de participação sem exigir resposta ou revelação.","hint":"Inclua uma escolha real e sem pressão.","errorFocus":"Convite coercitivo","misconceptions":{"“Você tem que brincar agora.”":["FORCED_PLAY"],"“Só pode ficar aqui se contar algo da sua família.”":["DISCLOSURE_CONDITION"],"“Vamos decidir por você.”":["DECIDE_FOR_OTHER"]},"position":2},{"id":"v5-re-inclusion-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"DESCRIBE","contextFamily":"LANGUAGE_DIFFERENCE","statement":"Em uma história, personagens usam palavras diferentes para cumprimentar. O que a turma pode fazer?","options":["Ouvir as formas apresentadas e descrevê-las sem rir nem dizer que uma pessoa vale menos.","Dizer que uma forma de falar é motivo para excluir.","Pedir que todos abandonem sua maneira de falar.","Afirmar que todas as pessoas de uma comunidade falam igual."],"correctAnswer":"Ouvir as formas apresentadas e descrevê-las sem rir nem dizer que uma pessoa vale menos.","explanation":"Diferença de expressão não é motivo para diminuir ou generalizar pessoas.","hint":"Como mostrar curiosidade com respeito?","errorFocus":"Hierarquizar fala ou generalizar grupo","misconceptions":{"Dizer que uma forma de falar é motivo para excluir.":["EXCLUDE_LANGUAGE"],"Pedir que todos abandonem sua maneira de falar.":["ERASE_DIFFERENCE"],"Afirmar que todas as pessoas de uma comunidade falam igual.":["GROUP_UNIFORMITY"]},"position":3},{"id":"v5-re-inclusion-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CLASSROOM_EXHIBIT","statement":"A turma prepara uma exposição de histórias fictícias. Uma criança não quer falar na frente de todos. Qual alternativa mantém sua participação possível?","options":["Obrigá-la a falar para provar que participou.","Oferecer que ela escolha outra contribuição, como organizar cartões ou passar a vez.","Pedir que um colega conte uma informação pessoal por ela.","Retirar seu nome da turma."],"correctAnswer":"Oferecer que ela escolha outra contribuição, como organizar cartões ou passar a vez.","explanation":"Participar pode ocorrer de formas diferentes; não é preciso expor uma criança para validar sua contribuição.","hint":"Procure outra opção voluntária, sem punição.","errorFocus":"Confundir participação com apresentação pública","misconceptions":{"Obrigá-la a falar para provar que participou.":["PUBLIC_SPEAKING_REQUIRED"],"Pedir que um colega conte uma informação pessoal por ela.":["PEER_PRIVATE_INFO"],"Retirar seu nome da turma.":["EXCLUSION"]},"position":4},{"id":"v5-re-inclusion-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"RESPOND","contextFamily":"UNWANTED_QUESTION","statement":"Um colega pergunta sobre uma prática familiar e a criança responde “prefiro não falar”. O que é adequado?","options":["Fazer a mesma pergunta de outro jeito até obter resposta.","Perguntar a toda a turma para comparar.","Aceitar a resposta e mudar de assunto sem insistir.","Dizer que a criança está escondendo algo."],"correctAnswer":"Aceitar a resposta e mudar de assunto sem insistir.","explanation":"O limite foi comunicado com clareza e deve ser respeitado.","hint":"O que a pessoa pediu ao dizer isso?","errorFocus":"Ignorar limite pessoal","misconceptions":{"Fazer a mesma pergunta de outro jeito até obter resposta.":["REPHRASE_PRESSURE"],"Perguntar a toda a turma para comparar.":["GROUP_COMPARISON"],"Dizer que a criança está escondendo algo.":["SUSPICION"]},"position":5},{"id":"v5-re-inclusion-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"DIFFERENT_CELEBRATIONS","statement":"Um calendário de histórias mostra celebrações diferentes. Qual pergunta ajuda a aprender sem colocar as celebrações em disputa?","options":["“Qual celebração é a melhor?”","“Por que todas as famílias fazem isso?”","“Quem não celebra desse jeito está errado?”","“O que o texto conta sobre essa celebração e que informação ainda não temos?”"],"correctAnswer":"“O que o texto conta sobre essa celebração e que informação ainda não temos?”","explanation":"Perguntas sobre a fonte e seus limites permitem conhecer sem hierarquizar ou generalizar.","hint":"Pergunte sobre o que foi apresentado, não sobre quem vale mais.","errorFocus":"Transformar comparação em competição","misconceptions":{"“Qual celebração é a melhor?”":["RANK_CELEBRATIONS"],"“Por que todas as famílias fazem isso?”":["UNIVERSALIZE"],"“Quem não celebra desse jeito está errado?”":["MORAL_JUDGMENT"]},"position":6},{"id":"v5-re-inclusion-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"CREATE","contextFamily":"INCLUSIVE_GAME_RULE","statement":"A turma quer uma regra para que personagens com preferências diferentes escolham atividades. Qual regra é mais inclusiva?","options":["Organizar turnos, oferecer opções e permitir passar a vez sem perder a participação futura.","Deixar a escolha sempre com a mesma pessoa.","Obrigar todos a escolher a atividade mais popular.","Retirar do jogo quem ainda está pensando."],"correctAnswer":"Organizar turnos, oferecer opções e permitir passar a vez sem perder a participação futura.","explanation":"A regra distribui escolhas e mantém a participação voluntária.","hint":"A regra inclui escolha, turno e opção de não responder agora?","errorFocus":"Maioria como obrigação","misconceptions":{"Deixar a escolha sempre com a mesma pessoa.":["FIXED_AUTHORITY"],"Obrigar todos a escolher a atividade mais popular.":["POPULARITY_AS_FORCE"],"Retirar do jogo quem ainda está pensando.":["PUNISH_THINKING"]},"position":7},{"id":"v5-re-inclusion-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"SHARED_AND_DIFFERENT","statement":"No conto, Nara e Tito gostam de animais, mas escolhem brincadeiras diferentes. Qual frase reconhece as duas informações?","options":["Eles gostam de tudo igual.","Eles têm um gosto em comum e preferências diferentes para brincar.","Um gosta de animais e o outro não.","A brincadeira preferida mostra quem é melhor."],"correctAnswer":"Eles têm um gosto em comum e preferências diferentes para brincar.","explanation":"A frase preserva a semelhança e a diferença descritas.","hint":"Não deixe uma informação apagar a outra.","errorFocus":"Apagar semelhança ou diferença","misconceptions":{"Eles gostam de tudo igual.":["IDENTICAL_IN_ALL"],"Um gosta de animais e o outro não.":["INVENTED_DIFFERENCE"],"A brincadeira preferida mostra quem é melhor.":["RANKING"]},"position":1},{"id":"v5-re-inclusion-lock-02","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"CHOOSE","contextFamily":"RESPECTFUL_RULE","statement":"Qual combinado respeita a escolha de quem não quer falar de algo pessoal?","options":["A pessoa precisa responder porque todos responderam.","Um amigo deve contar por ela.","A pessoa pode passar a vez e participar de outro modo.","A pessoa fica sem participar."],"correctAnswer":"A pessoa pode passar a vez e participar de outro modo.","explanation":"A escolha protege privacidade e mantém alternativas de participação.","hint":"A regra precisa respeitar o limite e preservar acesso.","errorFocus":"Obrigar ou excluir após recusa","misconceptions":{"A pessoa precisa responder porque todos responderam.":["MANDATORY_RESPONSE"],"Um amigo deve contar por ela.":["DISCLOSE_FOR_OTHER"],"A pessoa fica sem participar.":["EXCLUSION"]},"position":2},{"id":"v5-re-inclusion-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"GROUP_LABEL","statement":"Uma criança diz “quem gosta de cantar é sempre corajoso”. O que os personagens podem concluir?","options":["A frase vale para qualquer pessoa.","Quem não canta é covarde.","Só pessoas corajosas podem cantar.","O gosto por cantar não permite saber como todas as pessoas se sentem."],"correctAnswer":"O gosto por cantar não permite saber como todas as pessoas se sentem.","explanation":"Uma preferência não prova uma característica interna universal.","hint":"Que informação a história realmente dá?","errorFocus":"Criar rótulo a partir de gosto","misconceptions":{"A frase vale para qualquer pessoa.":["UNIVERSAL_TRAIT"],"Quem não canta é covarde.":["NEGATIVE_LABEL"],"Só pessoas corajosas podem cantar.":["RESTRICT_ACTIVITY"]},"position":3},{"id":"v5-re-inclusion-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"RESPOND","contextFamily":"HURT_REPAIR","statement":"Uma fala machuca um personagem por causa de uma diferença. Qual resposta inicial ajuda a reparar a situação?","options":["Interromper a fala, dizer que não é aceitável diminuir alguém e procurar apoio do educador.","Pedir que o personagem alvo explique sua diferença para merecer respeito.","Repetir a fala para ver se todos concordam.","Fingir que nada aconteceu sempre."],"correctAnswer":"Interromper a fala, dizer que não é aceitável diminuir alguém e procurar apoio do educador.","explanation":"O limite protege a pessoa e o apoio adulto ajuda a conduzir a reparação sem exposição adicional.","hint":"Proteja primeiro, sem exigir justificativa da pessoa atingida.","errorFocus":"Transferir a responsabilidade à pessoa alvo","misconceptions":{"Pedir que o personagem alvo explique sua diferença para merecer respeito.":["JUSTIFY_RESPECT"],"Repetir a fala para ver se todos concordam.":["AMPLIFY_HARM"],"Fingir que nada aconteceu sempre.":["IGNORE_ALWAYS"]},"position":4},{"id":"v5-re-inclusion-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"STORY_EVIDENCE","statement":"Uma história mostra dois personagens com costumes distintos participando da mesma atividade. Qual resposta se apoia melhor na evidência?","options":["Todos os personagens da história têm os mesmos costumes.","Eles conseguem participar juntos nessa situação, embora mantenham costumes diferentes.","Um costume precisa desaparecer para que convivam.","A história mostra que diferenças sempre desaparecem."],"correctAnswer":"Eles conseguem participar juntos nessa situação, embora mantenham costumes diferentes.","explanation":"A resposta descreve a situação mostrada sem generalizar para todos os casos.","hint":"Fique perto do que a história apresenta.","errorFocus":"Extrapolar além da evidência","misconceptions":{"Todos os personagens da história têm os mesmos costumes.":["UNSUPPORTED_UNIVERSAL"],"Um costume precisa desaparecer para que convivam.":["ERASURE_REQUIRED"],"A história mostra que diferenças sempre desaparecem.":["DIFFERENCE_DISAPPEARS"]},"position":5},{"id":"v5-re-inclusion-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"FICTIONAL_PREFERENCES","statement":"Dora gosta de ouvir histórias e Ivo também; Ivo prefere desenhar depois. Que semelhança está no texto?","options":["Os dois preferem desenhar depois.","Dora não gosta de histórias.","Dora e Ivo gostam de ouvir histórias.","Ivo é melhor por desenhar."],"correctAnswer":"Dora e Ivo gostam de ouvir histórias.","explanation":"A preferência comum é ouvir histórias; o texto só informa que Ivo também desenha depois.","hint":"Repita a informação que vale para os dois.","errorFocus":"Ampliar a semelhança sem evidência","misconceptions":{"Os dois preferem desenhar depois.":["TRANSFER_PREFERENCE"],"Dora não gosta de histórias.":["REVERSE_PREFERENCE"],"Ivo é melhor por desenhar.":["RANKING"]},"position":1},{"id":"v5-re-inclusion-review-02","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"INCLUDE","contextFamily":"TURN_TAKING","statement":"Duas crianças querem escolher primeiro. Qual regra pode ajudar?","options":["Deixar escolher sempre quem chegou primeiro.","Cancelar todas as escolhas.","Fazer uma criança sair.","Alternar quem escolhe em cada rodada."],"correctAnswer":"Alternar quem escolhe em cada rodada.","explanation":"A alternância distribui oportunidades de escolha.","hint":"Como cada uma pode ter sua vez?","errorFocus":"Turno permanente ou exclusão","misconceptions":{"Deixar escolher sempre quem chegou primeiro.":["PERMANENT_PRIORITY"],"Cancelar todas as escolhas.":["NO_CHOICE"],"Fazer uma criança sair.":["EXCLUDE"]},"position":2},{"id":"v5-re-inclusion-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"RESPECT","contextFamily":"PRIVATE_PREFERENCE","statement":"Um personagem não quer explicar por que prefere uma atividade. O que os colegas devem fazer?","options":["Respeitar a escolha e continuar sem exigir explicação pessoal.","Perguntar repetidamente até descobrir.","Inventar um motivo e contar aos outros.","Impedir que ele escolha novamente."],"correctAnswer":"Respeitar a escolha e continuar sem exigir explicação pessoal.","explanation":"Uma preferência não precisa vir acompanhada de justificativa privada.","hint":"O personagem já indicou seu limite?","errorFocus":"Exigir explicação ou inventar motivo","misconceptions":{"Perguntar repetidamente até descobrir.":["REPEAT_QUESTION"],"Inventar um motivo e contar aos outros.":["INVENT_MOTIVE"],"Impedir que ele escolha novamente.":["REMOVE_CHOICE"]},"position":3},{"id":"v5-re-inclusion-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DESCRIBE","contextFamily":"MULTIPLE_QUALITIES","statement":"Qual frase descreve melhor um personagem sem reduzi-lo a uma só característica?","options":["Téo é quieto, então nunca quer participar.","Téo gosta de histórias, ajuda a organizar materiais e prefere pensar antes de falar.","Téo gosta de uma coisa e não pode gostar de outra.","Téo representa todas as crianças da turma."],"correctAnswer":"Téo gosta de histórias, ajuda a organizar materiais e prefere pensar antes de falar.","explanation":"A descrição reúne informações dadas e evita transformar uma característica em regra.","hint":"Inclua mais de um aspecto sem generalizar.","errorFocus":"Rótulo por uma característica","misconceptions":{"Téo é quieto, então nunca quer participar.":["ONE_TRAIT_AS_ALL"],"Téo gosta de uma coisa e não pode gostar de outra.":["ONLY_ONE_INTEREST"],"Téo representa todas as crianças da turma.":["REPRESENTS_GROUP"]},"position":4},{"id":"v5-re-inclusion-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"COSTUME_STORY","statement":"Um conto mostra uma roupa usada por uma personagem numa ocasião especial. O que a turma pode afirmar?","options":["Toda pessoa do mesmo grupo usa essa roupa.","A roupa prova que a personagem é melhor.","O conto mostra essa roupa para a personagem; não basta para dizer que todos usam o mesmo traje.","A turma deve pedir que colegas usem uma igual."],"correctAnswer":"O conto mostra essa roupa para a personagem; não basta para dizer que todos usam o mesmo traje.","explanation":"Um exemplo não representa automaticamente todas as pessoas de um grupo.","hint":"Limite a frase ao personagem e à fonte.","errorFocus":"Generalizar um exemplo","misconceptions":{"Toda pessoa do mesmo grupo usa essa roupa.":["COSTUME_UNIVERSAL"],"A roupa prova que a personagem é melhor.":["CLOTHING_RANK"],"A turma deve pedir que colegas usem uma igual.":["COERCE_CLOTHING"]},"position":5},{"id":"v5-re-inclusion-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"RESPOND","contextFamily":"RESPECTFUL_CURIOSITY","statement":"Uma criança quer conhecer um costume descrito num livro, mas não conhece ninguém que queira conversar sobre isso. O que pode fazer?","options":["Escolher um colega e exigir uma explicação.","Afirmar que o livro vale para todas as pessoas.","Fazer piada até alguém responder.","Consultar o próprio livro ou perguntar ao educador, sem pressionar colegas a representar um grupo."],"correctAnswer":"Consultar o próprio livro ou perguntar ao educador, sem pressionar colegas a representar um grupo.","explanation":"Curiosidade pode ser atendida por fontes e mediação sem impor representação ou exposição.","hint":"Como buscar informação sem colocar uma criança nessa obrigação?","errorFocus":"Obrigar colega a representar grupo","misconceptions":{"Escolher um colega e exigir uma explicação.":["FORCED_EXPERT"],"Afirmar que o livro vale para todas as pessoas.":["BOOK_AS_UNIVERSAL"],"Fazer piada até alguém responder.":["RIDICULE_TO_GET_ANSWER"]},"position":6},{"id":"v5-re-inclusion-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"CHOOSE","contextFamily":"ACCESSIBLE_PARTICIPATION","statement":"Um personagem prefere responder apontando figuras em vez de falar na roda. Como a turma pode acolher essa forma de participação?","options":["Aceitar a resposta por figuras e oferecer outras opções sem obrigar a falar.","Exigir fala para considerar a resposta válida.","Pedir que outro personagem fale por ele sem autorização.","Retirar sua vez porque respondeu de outro modo."],"correctAnswer":"Aceitar a resposta por figuras e oferecer outras opções sem obrigar a falar.","explanation":"Formas diferentes de expressão podem permitir participação sem coerção.","hint":"O objetivo é responder ou falar de um jeito específico?","errorFocus":"Confundir participação com modalidade única","misconceptions":{"Exigir fala para considerar a resposta válida.":["SPEECH_ONLY"],"Pedir que outro personagem fale por ele sem autorização.":["SPEAK_FOR_OTHER"],"Retirar sua vez porque respondeu de outro modo.":["PUNISH_ALTERNATIVE"]},"position":7},{"id":"v5-re-inclusion-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SOURCE_LIMITS","statement":"Um texto conta a experiência de uma personagem. Qual frase evita transformar esse relato numa regra sobre todos?","options":["“Todo mundo faz assim.”","“Nesta história, a personagem faz assim”; para saber mais, precisamos de outras fontes.","“Uma pessoa contou, então todos pensam igual.”","“A personagem prova que uma tradição é melhor.”"],"correctAnswer":"“Nesta história, a personagem faz assim”; para saber mais, precisamos de outras fontes.","explanation":"Um relato informa sobre a personagem, não representa automaticamente todas as pessoas.","hint":"Nomeie a fonte e limite a conclusão ao que ela mostra.","errorFocus":"Generalizar um relato individual","misconceptions":{"“Todo mundo faz assim.”":["UNIVERSAL_FROM_ONE"],"“Uma pessoa contou, então todos pensam igual.”":["SAME_BELIEF"],"“A personagem prova que uma tradição é melhor.”":["RANK_FROM_STORY"]},"position":8},{"id":"v5-re-inclusion-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"INCLUSIVE_DECISION","statement":"Uma brincadeira pode ser escolhida por várias pessoas, mas uma criança não quer participar agora. Qual decisão acolhe sem excluir?","options":["Obrigá-la a brincar para provar amizade.","Proibi-la de voltar depois.","Manter o convite aberto e permitir que ela escolha outra forma ou momento de participar.","Decidir que a preferência dela está errada."],"correctAnswer":"Manter o convite aberto e permitir que ela escolha outra forma ou momento de participar.","explanation":"Acolher combina convite, escolha e possibilidade de participação sem punição.","hint":"A opção preserva escolha e pertencimento?","errorFocus":"Coerção ou exclusão disfarçada de inclusão","misconceptions":{"Obrigá-la a brincar para provar amizade.":["FORCE_FRIENDSHIP"],"Proibi-la de voltar depois.":["BAN_RETURN"],"Decidir que a preferência dela está errada.":["RANK_PREFERENCE"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-religious-self-other-inclusion',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-religious-self-other-inclusion' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'RELIGIOUS_EDUCATION', 'CONVIVENCIA', 'semelhancas diferencas e acolhimento em personagens e situacoes',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

